import{getCurrentPlaceByName}from"./getCurrentPlace.js";import initializePage from"./initializePage.js";import{showHistory,clearHistory}from"./history.js";function handleResize(){if(window.innerWidth<=600){const e=document.querySelector(".header__left .search-input"),t=document.querySelector(".history .actions"),o=document.querySelector(".header__left .desktop-button");e&&t&&t.prepend(e),o&&o.remove()}}initializePage(),showHistory(),handleResize(),window.addEventListener("resize",handleResize);const searchInput=document.querySelector(".search-input input");searchInput&&searchInput.addEventListener("keydown",(e=>{"Enter"===e.key&&(getCurrentPlaceByName(e.target.value),e.target.value="")}));const closeHistoryButton=document.querySelector(".history button");closeHistoryButton&&closeHistoryButton.addEventListener("click",(()=>{document.querySelector(".history").classList.remove("show")}));const openHistoryButton=document.querySelector(".header__left button");openHistoryButton&&openHistoryButton.addEventListener("click",(()=>{document.querySelector(".history").classList.add("show")}));const clearHistoryButton=document.querySelector(".history__clear");clearHistoryButton&&clearHistoryButton.addEventListener("click",(()=>{clearHistory()}));